theory.body:
@Bean Queue → RabbitAdmin tworzy kolejkę na brokerze.
@Bean DirectExchange → RabbitAdmin tworzy exchange na brokerze.
@Bean Binding (łączy Queue + Exchange + routing key) → RabbitAdmin rejestruje powiązanie na brokerze.

Wszystko dzieje się automatycznie przy starcie kontekstu Springa, zanim jakikolwiek kod aplikacji wyśle pierwszą wiadomość.

theory.code:
@Bean
Queue kolejkaZamowien() {
    return new Queue("zamowienia.kolejka.amqp", false, false, true);
}

@Bean
DirectExchange zamowieniaExchange() {
    return new DirectExchange("zamowienia.exchange.amqp", false, true);
}

@Bean
Binding bindowanie(Queue kolejkaZamowien, DirectExchange zamowieniaExchange) {
    return BindingBuilder.bind(kolejkaZamowien)
        .to(zamowieniaExchange)
        .with("zamowienie.utworzone");
}

rabbitTemplate.convertAndSend(
    "zamowienia.exchange.amqp", "zamowienie.utworzone", "Zamowienie Z300");

@Component
class OdbiorcaZamowien {

    @RabbitListener(queues = "zamowienia.kolejka.amqp")
    public void naZamowienie(String tresc) {
        System.out.println("Odebrano przez AMQP: " + tresc);
    }
}

try {
    ConfigurableApplicationContext context = SpringApplication.run(Demo.class, args);
    // ... wyslij/odbierz wiadomosc ...
} catch (Exception e) {
    System.out.println("Broker RabbitMQ niedostepny - kod jest poprawny i zadzialalby");
    System.out.println("identycznie z prawdziwym brokerem (np. docker run -p 5672:5672 rabbitmq).");
}

// brak @Bean Queue/DirectExchange/Binding w konfiguracji

rabbitTemplate.convertAndSend("zamowienia.exchange.amqp", "zamowienie.utworzone", tresc);
// AmqpException: exchange 'zamowienia.exchange.amqp' nie istnieje na brokerze

@Bean Queue kolejkaZamowien() { return new Queue("zamowienia.kolejka.amqp", false, false, true); }
@Bean DirectExchange zamowieniaExchange() { return new DirectExchange("zamowienia.exchange.amqp"); }
@Bean Binding bindowanie(Queue q, DirectExchange e) {
    return BindingBuilder.bind(q).to(e).with("zamowienie.utworzone");
}
// teraz convertAndSend dziala poprawnie - topologia istnieje na brokerze
